    const T av = a[x * CH + c];
    const T bv = (MODE == 0 || MODE == 2) ? b[x * CH + c] : p.cst[c];
    const bool hit = (MODE == 2 || MODE == 3)
                         ? (fabsf((float)av - (float)bv) <= p.eps)
                         : tcComp(av, bv, p.op);
    if (!hit) { all = false; break; }
  }
  dr[x] = all ? (Npp8u)0xFF : (Npp8u)0;
}

